package org.jlinalg.enrichment;

import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class FumaMagmaReportTest {
    private static final FumaMagmaReport.Limits LIMITS=new FumaMagmaReport.Limits(1000,100000,10000,100000);
    private static final List<String> SET_COLUMNS=List.of("FULL_NAME","NGENES","BETA","BETA_STD","SE","P");
    private static FumaMagmaReport.Table genes(){return new FumaMagmaReport.Table(List.of("GENE","ZSTAT"),List.of(List.of("E1","2"),List.of("E2","-1"),List.of("Absent","0"),List.of("E1","4")));}
    private static FumaMagmaReport.Table sets(String... p){var rows=new ArrayList<List<String>>();for(int i=0;i<p.length;i++)rows.add(List.of("Set "+(i+1),"3",".25",".5",".125",p[i]));return new FumaMagmaReport.Table(SET_COLUMNS,rows);}
    private static FumaMagmaReport.Result run(FumaMagmaReport.Table genes,List<FumaMagmaReport.Gene> annotation,FumaMagmaReport.Table sets){return FumaMagmaReport.report(genes,annotation,sets,FumaMagmaReport.Duplicates.SOURCE_FIRST,FumaMagmaReport.MissingP.SOURCE_NA,FumaMagmaReport.Placeholders.SOURCE_ROWS,LIMITS,()->{});}
    private static FumaMagmaReport.Result run(String... p){return run(genes(),List.of(new FumaMagmaReport.Gene("E1","First"),new FumaMagmaReport.Gene("E2","")),sets(p));}
    @Test void firstSymbolEmptyAndUnmatchedRemainDistinct(){var r=run(genes(),List.of(new FumaMagmaReport.Gene("E1","First"),new FumaMagmaReport.Gene("E1","Later"),new FumaMagmaReport.Gene("E2","")),sets(".001",".03",".2"));assertEquals(List.of("First","","NA","First"),r.genes().rows().stream().map(row->row.get(2)).toList());assertEquals(List.of(1,3,0,1),r.geneJoins().stream().map(FumaMagmaReport.GeneJoin::annotationRow).toList());assertEquals(1,r.duplicateAnnotationRows());assertEquals(1,r.emptySymbols());assertEquals(1,r.missingSymbols());assertEquals("matched-empty-symbol",r.geneJoins().get(1).status());assertEquals("unmatched",r.geneJoins().get(2).status());}
    @Test void nullFirstSymbolIsNeverReplacedByLaterMatch(){var r=run(genes(),List.of(new FumaMagmaReport.Gene("E1",null),new FumaMagmaReport.Gene("E1","Later")),sets(".1"));assertEquals("NA",r.genes().rows().get(0).get(2));assertEquals(1,r.geneJoins().get(0).annotationRow());assertEquals("matched-missing-symbol",r.geneJoins().get(0).status());}
    @Test void existingSymbolAndPbonAreOverwrittenInPlace(){var g=new FumaMagmaReport.Table(List.of("SYMBOL","GENE","extra"),List.of(List.of("Old","E1","unchanged")));var s=new FumaMagmaReport.Table(List.of("Pbon","FULL_NAME","NGENES","BETA","BETA_STD","SE","P"),List.of(List.of("Old","Set","3",".1",".2",".3",".01")));var r=run(g,List.of(new FumaMagmaReport.Gene("E1","Current")),s);assertEquals(g.columns(),r.genes().columns());assertEquals(List.of("Current","E1","unchanged"),r.genes().rows().get(0));assertEquals(s.columns(),r.allSets().columns());assertEquals("0.01",r.allSets().rows().get(0).get(0));}
    @Test void sourcePbonUsesHolmRatherThanBonferroni(){var r=run(".0001",".001",".002",".004",".006",".008",".01",".02",".03",".04",".5",".7");double[] expected={.0012,.011,.02,.036,.048,.056,.06,.1,.12,.12,1,1};for(int i=0;i<expected.length;i++)assertEquals(expected[i],r.allTests().get(i).holm(),Math.ulp(expected[i])*2);assertEquals(5,r.significantSets());assertEquals(12,r.correctionFamilySize());assertEquals(10,r.displayedSets().rows().size());assertEquals(12,r.allSets().rows().size());}
    @Test void topTenCanContainNonsignificantTestsAndPadding(){var r=run(".001",".03",".2");assertEquals("source-top-ten",r.displayBranch());assertEquals(1,r.significantSets());assertEquals(7,r.placeholderRows());assertEquals(List.of(1,2,3,0,0,0,0,0,0,0),r.displayRows().stream().map(FumaMagmaReport.DisplayRow::sourceRow).toList());for(var row:r.displayedSets().rows().subList(3,10))assertTrue(row.stream().allMatch("NA"::equals));}
    @Test void atLeastTenSignificantReturnsAllSignificantRows(){var p=new String[12];for(int i=0;i<p.length;i++)p[i]=Double.toString((i+1)*1e-6);var r=run(p);assertEquals("source-significant",r.displayBranch());assertEquals(12,r.displayedSets().rows().size());assertEquals(12,r.significantSets());assertEquals(0,r.placeholderRows());}
    @Test void exactlyTenSignificantDoesNotRetainNonsignificantRows(){var p=new String[12];for(int i=0;i<10;i++)p[i]=Double.toString((i+1)*1e-6);p[10]=".8";p[11]=".9";var r=run(p);assertEquals("source-significant",r.displayBranch());assertEquals(10,r.significantSets());assertEquals(10,r.displayedSets().rows().size());}
    @Test void missingPIsExcludedFromTheLazyRDefaultFamily(){var r=run(".02","NA",".001",".02",".5");assertEquals(4,r.correctionFamilySize());assertEquals(1,r.missingPValues());assertEquals(.004,r.allTests().get(2).holm(),0);assertNull(r.allTests().get(1).holm());assertEquals(List.of(3,1,4,5,2),r.displayRows().subList(0,5).stream().map(FumaMagmaReport.DisplayRow::sourceRow).toList());assertEquals("Set 2",r.displayedSets().rows().get(4).get(0));}
    @Test void significantBranchMissingLogicalIndexCreatesExplicitAllMissingRow(){var p=new String[12];for(int i=0;i<11;i++)p[i]=Double.toString((i+1)*1e-6);p[11]="NA";var r=run(p);assertEquals(11,r.correctionFamilySize());assertEquals(11,r.significantSets());assertEquals(12,r.displayedSets().rows().size());assertEquals(1,r.placeholderRows());assertEquals(12,r.displayRows().get(11).sourceRow());assertEquals("source-significant-branch-NA-index",r.displayRows().get(11).status());assertTrue(r.displayedSets().rows().get(11).stream().allMatch("NA"::equals));assertEquals(3.6e-5,r.allTests().get(10).holm(),Math.ulp(3.6e-5)*2);}
    @Test void strictSignificanceBoundaryAndStablePTiesAreRetained(){var r=run(".025",".025");assertEquals(0,r.significantSets());assertEquals(.05,r.allTests().get(0).holm(),0);assertEquals(List.of(1,2),r.displayRows().subList(0,2).stream().map(FumaMagmaReport.DisplayRow::sourceRow).toList());var z=run("-0.0","0","1e-300");assertEquals(List.of(1,2,3),z.displayRows().subList(0,3).stream().map(FumaMagmaReport.DisplayRow::sourceRow).toList());assertEquals(0,z.allTests().get(0).holm(),0);assertEquals(1e-300,z.allTests().get(2).holm(),0);}
    @Test void allMissingPProducesNoFiniteTestsAndOnlyDeclaredPlaceholders(){var r=run("NA","NA");assertEquals(0,r.correctionFamilySize());assertEquals(0,r.significantSets());assertEquals(8,r.placeholderRows());assertEquals(2,r.missingPValues());assertEquals("Set 1",r.displayedSets().rows().get(0).get(0));}
    @Test void artificialRowsRequireExplicitSourcePolicy(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.ERROR,LIMITS,()->{}));}
    @Test void missingPRequiresExplicitPolicy(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets("NA"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,LIMITS,()->{}));}
    @Test void duplicateAnnotationRequiresExplicitPolicy(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(new FumaMagmaReport.Gene("E1","A"),new FumaMagmaReport.Gene("E1","B")),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,LIMITS,()->{}));}
    @Test void invalidProbabilitiesAreRejectedDespiteSourceAcceptance(){for(String p:List.of("-.1","1.5","NaN","Inf","1e9999","0x1.0p-2",""," ",".2 "))assertThrows(IllegalArgumentException.class,()->run(p),p);assertThrows(IllegalArgumentException.class,()->run(new String[0]));}
    @Test void missingColumnsAndInvalidTextCannotBecomeReportValues(){assertThrows(IllegalArgumentException.class,()->run(new FumaMagmaReport.Table(List.of("ID"),List.of()),List.of(),sets(".2")));assertThrows(IllegalArgumentException.class,()->run(genes(),List.of(),new FumaMagmaReport.Table(List.of("P"),List.of(List.of(".2")))));assertThrows(IllegalArgumentException.class,()->new FumaMagmaReport.Table(List.of("A","A"),List.of()));assertThrows(IllegalArgumentException.class,()->new FumaMagmaReport.Table(List.of("A"),List.of(List.of("1","2"))));assertThrows(IllegalArgumentException.class,()->new FumaMagmaReport.Gene("NA","X"));assertThrows(IllegalArgumentException.class,()->new FumaMagmaReport.Gene("E1","bad\ttext"));}
    @Test void completeInputRowsAndCellsAreBounded(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,new FumaMagmaReport.Limits(3,10000,1000,10000),()->{}));assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,new FumaMagmaReport.Limits(100,10,1000,10000),()->{}));}
    @Test void completeOutputIncludingHiddenFamilyAndPlaceholdersIsBounded(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,new FumaMagmaReport.Limits(100,10000,18,10000),()->{}));}
    @Test void operationAndCancellationLimitsFailRatherThanTruncate(){assertThrows(IllegalArgumentException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,new FumaMagmaReport.Limits(100,10000,1000,1),()->{}));var calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->FumaMagmaReport.report(genes(),List.of(),sets(".01"),FumaMagmaReport.Duplicates.ERROR,FumaMagmaReport.MissingP.ERROR,FumaMagmaReport.Placeholders.SOURCE_ROWS,LIMITS,()->{if(calls.incrementAndGet()==2)throw new IllegalStateException("cancelled");}));}
    @Test void immutableInputsAndCompleteResultPopulationsPreserveRawFitFields(){var inner=new ArrayList<>(List.of("E1","2"));var g=new FumaMagmaReport.Table(List.of("GENE","ZSTAT"),List.of(inner));inner.set(1,"999");var r=run(g,List.of(new FumaMagmaReport.Gene("E1","symbol")),sets(".01"));assertEquals("2",r.genes().rows().get(0).get(1));assertThrows(UnsupportedOperationException.class,()->r.genes().rows().get(0).set(1,"3"));assertThrows(UnsupportedOperationException.class,()->r.allTests().clear());assertEquals(".25",r.displayedSets().rows().get(0).get(2));assertEquals(".01",r.allSets().rows().get(0).get(5));}
}
